/**
 * Social preview card URLs.
 *
 * The og:image has to be absolute for crawlers, but the origin differs per
 * deployment: the static landing lives on Cloudflare Pages and the full app
 * on the VPS. VITE_SITE_ORIGIN carries the canonical origin at build time;
 * falling back to the current origin keeps local dev and any preview
 * deployment working without configuration.
 */
export const SITE_ORIGIN: string =
  (import.meta.env.VITE_SITE_ORIGIN as string | undefined) ?? globalThis.location?.origin ?? "";

/** The og card, generated by scripts/og-preview/build-og-preview.sh. */
export const OG_PREVIEW_PATH = "/og-preview.png";

export const OG_PREVIEW_URL = `${SITE_ORIGIN}${OG_PREVIEW_PATH}`;
